## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;

  // ------------------------------------------------------------
  // Parameters and clock generation
  // ------------------------------------------------------------
  localparam int CLK_PERIOD = 8;                 // 125 MHz
  localparam logic [15:0] PRESCALE_VAL = 16'd5;  // same as baseline regression

  logic clk = 1'b0;
  always #(CLK_PERIOD/2) clk = ~clk;

  // ------------------------------------------------------------
  // DUT reset
  // ------------------------------------------------------------
  logic rst = 1'b1;

  // ------------------------------------------------------------
  // AXI‑Stream side of the UART (TX side – not used for coverage)
  // ------------------------------------------------------------
  logic [7:0] s_axis_tdata;
  logic       s_axis_tvalid;
  logic       s_axis_tready;

  // ------------------------------------------------------------
  // AXI‑Stream side of the UART (RX side)
  // ------------------------------------------------------------
  logic [7:0] m_axis_tdata;
  logic       m_axis_tvalid;
  logic       m_axis_tready;   // driven by the testbench

  // ------------------------------------------------------------
  // UART interface signals
  // ------------------------------------------------------------
  logic txd;
  logic rxd_drv;                     // drives the rxd input of the DUT
  logic tx_busy;
  logic rx_busy;
  logic rx_overrun_error;
  logic rx_frame_error;

  // ------------------------------------------------------------
  // Configuration
  // ------------------------------------------------------------
  logic [15:0] prescale = PRESCALE_VAL;

  // ------------------------------------------------------------
  // Drivers
  // ------------------------------------------------------------
  logic tready_drv = 1'b0;            // drives m_axis_tready (keep low)
  logic rxd_driver = 1'b1;            // idle state of the UART receive line

  // ------------------------------------------------------------
  // DUT instantiation
  // ------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),

    // AXI input side (TX)
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),

    // AXI output side (RX)
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(tready_drv),

    // UART pins
    .txd          (txd),
    .rxd          (rxd_driver),

    // Status outputs
    .tx_busy      (tx_busy),
    .rx_busy      (rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),

    // Configuration
    .prescale     (prescale)
  );

  // ------------------------------------------------------------
  // Helper tasks
  // ------------------------------------------------------------
  task automatic wait_clks(input int n);
    repeat (n) @(posedge clk);
  endtask

  // Sends one UART frame on rxd_driver.
  // data_byte – payload (LSB first)
  // stop_low  – 1 = stop bit forced low (causes frame_error),
  //             0 = normal stop bit (high)
  task automatic uart_send_frame(input byte unsigned data_byte,
                                 input logic stop_low);
    int bit_time;
    bit_time = int'(prescale) * 8;

    // Idle (high)
    rxd_driver = 1'b1;

    // Start bit (low)
    rxd_driver = 1'b0;
    wait_clks(bit_time);

    // Data bits, LSB first
    for (int i = 0; i < 8; i++) begin
      rxd_driver = data_byte[i];
      wait_clks(bit_time);
    end

    // Stop bit
    if (stop_low) rxd_driver = 1'b0; else rxd_driver = 1'b1;
    wait_clks(bit_time);

    // Return to idle
    rxd_driver = 1'b1;
  endtask

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // ----------------------------------------------------------------
    // Reset release
    // ----------------------------------------------------------------
    rst = 1'b1;
    wait_clks(2);
    rst = 1'b0;
    wait_clks(2);

    // ----------------------------------------------------------------
    // Phase 1 – put a frame (0x3C) on the line with a *low* stop bit.
    // This asserts frame_error while the receiver holds m_axis_tdata = 0x3C
    // and m_axis_tvalid = 1, but tready stays low → st becomes 1.
    // ----------------------------------------------------------------
    tready_drv = 1'b0;                                 // never accept
    uart_send_frame(8'h3C, 1'b1);                       // stop bit low → frame_error
    // Give the DUT time to latch the word and assert frame_error
    wait_clks(12);
    // Keep the interface idle for a while
    wait_clks(20);

    // ----------------------------------------------------------------
    // Phase 2 – transmit a second frame (0xA5) with a normal stop bit.
    // Because the first word is still un‑handshaked, this generates
    // overrun_error while m_axis_tdata becomes 0xA5 and m_axis_tvalid
    // stays high.  At the next rising edge all conditions for
    // cov_R26_frame_error_then_overrun are satisfied.
    // ----------------------------------------------------------------
    // Still keep tready low
    uart_send_frame(8'hA5, 1'b0);                       // normal stop bit
    // Allow a few cycles for overrun_error and the handshake flag to settle
    wait_clks(6);

    // ----------------------------------------------------------------
    // Coverage hit achieved – end simulation cleanly.
    // ----------------------------------------------------------------
    $finish;
  end

endmodule
